import { tv, type VariantProps } from "@/lib/beton/tv";

export const stat = tv({
  slots: {
    root: "flex flex-col gap-1 border-3 border-border bg-raised shadow-sm",
    label: "font-mono text-xs font-bold tracking-widest uppercase",
    value: "font-display font-black tracking-tight text-foreground tabular-nums",
    delta: "inline-flex items-center gap-1 font-mono text-sm font-bold",
    deltaIcon: "size-4",
    description: "text-sm text-foreground",
  },
  variants: {
    size: {
      sm: { root: "p-4", value: "text-h3" },
      md: { root: "p-5", value: "text-h2" },
      lg: { root: "p-6", value: "text-h1" },
    },
    trend: {
      up: { delta: "text-foreground" },
      down: { delta: "text-foreground" },
      flat: { delta: "text-foreground" },
    },
  },
  defaultVariants: {
    size: "md",
    trend: "flat",
  },
});

export type StatVariants = VariantProps<typeof stat>;

import { stat, type StatVariants } from "@/lib/beton/recipes/stat.recipe";
import { visuallyHidden } from "@/lib/beton/shared";
import type { ComponentProps, ReactNode } from "react";
import { ChevronDownIcon, ChevronUpIcon, MinusIcon } from "@/lib/beton/icons";

export interface StatProps extends ComponentProps<"div">, Omit<StatVariants, "trend"> {
  /** What the number measures. */
  label: ReactNode;
  /** The number itself. */
  value: ReactNode;
  /** The change since last time, such as "+12%". */
  delta?: ReactNode;
  /** Which way the change went. Says so in words as well as with an arrow. */
  trend?: "up" | "down" | "flat";
  /** A line of context under the number. */
  description?: ReactNode;
}

const TREND_LABEL = { up: "up", down: "down", flat: "no change" } as const;

/** A single number with its label, its change and a line of context. */
export function Stat({
  size = "md",
  label,
  value,
  delta,
  trend = "flat",
  description,
  className,
  children,
  ...props
}: StatProps) {
  const styles = stat({ size, trend });
  const TrendIcon = trend === "up" ? ChevronUpIcon : trend === "down" ? ChevronDownIcon : MinusIcon;
  return (
    <div {...props} data-trend={trend} className={styles.root({ class: className })}>
      <p className={styles.label()}>{label}</p>
      <p className={styles.value()}>{value}</p>
      {delta ? (
        <p className={styles.delta()}>
          <TrendIcon className={styles.deltaIcon()} />
          {delta}
          <span className={visuallyHidden}> ({TREND_LABEL[trend]})</span>
        </p>
      ) : null}
      {description ? <p className={styles.description()}>{description}</p> : null}
      {children}
    </div>
  );
}
